import{_ as n,o as e,c as a,ag as p}from"./chunks/framework.DUTPmUpA.js";const i="/_assets/eventTypeOfPredefinedEvents.Cfc86yXg.png",m=JSON.parse('{"title":"События и таймеры в Typescript","description":"","frontmatter":{"title":"События и таймеры в Typescript","author":"Shush","steamId":76561197994333650,"date":"05.10.2022"},"headers":[],"relativePath":"scripting/Typescript/typescript-events.md","filePath":"scripting/Typescript/typescript-events.md"}'),t={name:"scripting/Typescript/typescript-events.md"};function l(c,s,r,o,d,u){return e(),a("div",null,[...s[0]||(s[0]=[p(`<h1 id="события-и-таимеры-в-typescript" tabindex="-1">События и таймеры в Typescript <a class="header-anchor" href="#события-и-таимеры-в-typescript" aria-label="Permalink to &quot;События и таймеры в Typescript&quot;">​</a></h1><p>Как вы, возможно, знаете, в Доте проводится множество мероприятий. При разработке собственной игры прослушивание событий очень полезно, поскольку позволяет вам что-то делать, когда что-то происходит. Например, прослушивание события, которое срабатывает при смерти, когда погибает герой, юнит или здание. События предоставят некоторую информацию об экземпляре этого события. Например, в приведенном выше событии в параметры будут включены убийца и жертва.</p><h2 id="важное-примечание-прежде-чем-мы-начнем" tabindex="-1">Важное примечание, прежде чем мы начнем <a class="header-anchor" href="#важное-примечание-прежде-чем-мы-начнем" aria-label="Permalink to &quot;Важное примечание, прежде чем мы начнем&quot;">​</a></h2><p>В этом разделе есть множество асинхронных функций, которые имеют обратные вызовы в качестве аргументов. Если вы не знаете, что это такое, на W3Schools есть отличные и понятные статьи, объясняющие <a href="https://www.w3schools.com/js/js_callback.asp" target="_blank" rel="noreferrer">callbacks</a> и <a href="https://www.w3schools.com/js/js_asynchronous.asp" target="_blank" rel="noreferrer">async functions</a> по этому вопросу.</p><p>В этом руководстве будут рассмотрены и объяснены коды, написанные в шаблоне Typescript. Если у вас его нет, прочтите инструкции по <a href="./typescript-introduction">Typescript Introduction</a>. Хотя в качестве примеров будет использоваться написанный код, не стесняйтесь поэкспериментировать с шаблоном и по-настоящему понять, как все это связано друг с другом.</p><h2 id="встроенные-события" tabindex="-1">Встроенные события <a class="header-anchor" href="#встроенные-события" aria-label="Permalink to &quot;Встроенные события&quot;">​</a></h2><p>Встроенные события, которых много, не могут быть изменены с точки зрения того, когда они запускаются и какие параметры предоставляются, так что имейте это в виду. Однако вы можете добавить прослушиватель к событию с помощью функции обратного вызова — функции, которая будет запускаться при срабатывании этого события.</p><p>Откройте файл <code>GameMode.ts</code> в папке <code>/src/vscripts</code> вашего проекта. Там вы можете найти примеры событий, которые мы слушаем. Например, возьмем следующее событие:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>ListenToGameEvent(&#39;npc_spawned&#39;, (event) =&gt; this.OnNpcSpawned(event), undefined);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Вызов <code>ListenToGameEvent</code> создает нового прослушивателя этого события. В первом аргументе должно быть указано допустимое имя события. Typescript знает, какие имена событий разрешены, и отклонит любое другое имя, которое не является одним из известных событий. Мало того, он также знает, какие типы параметров передает каждое событие. Вы можете использовать intellisense вашей IDE (например, в VSCode по умолчанию это Ctrl + пробел), чтобы отобразить имена всех событий, а затем просто выбрать нужное событие.</p><p>Затем вторым аргументом является функция обратного вызова. Обратите внимание, что он имеет синтаксис <code>event =&gt; SomeFunctionName(event)</code>, называемый синтаксисом выражения стрелочной функции. Это используется для определения функции, которая будет запускаться при срабатывании события. Учитывая объект <code>event</code>, описывающий событие, функция вызывается и выполняется так же, как и любой другой код.</p><p>Функция может быть внешней функцией, например <code>this.OnNpcSpawned</code> в приведенном выше примере, где она определена, или вы можете записать тело функции прямо здесь. Например:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>ListenToGameEvent(</span></span>
<span class="line"><span>  &#39;npc_spawned&#39;,</span></span>
<span class="line"><span>  (event) =&gt; {</span></span>
<span class="line"><span>    print(&#39;we just fired npc spawned event!&#39;);</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  undefined,</span></span>
<span class="line"><span>);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>I do not recommend writing function bodies in this manner unless it is a few lines at most, as the code can get messy and not very readable.</p></div><p>As was already stated, Typescript knows what are the parameters provided when an event is triggered. They are stored in an object that we call <code>event</code>. If we&#39;re using an external function, that function should expect that event, which makes sure it is only used when the appropriate event runs.</p><p>In the example of <code>this.OnNpcSpawned(event)</code>, we defined an external function in the same class to call whenever the event triggers, which looks like this:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>OnNpcSpawned(event: NpcSpawnedEvent) {</span></span>
<span class="line"><span>    // After a hero unit spawns, apply modifier_panic for 8 seconds</span></span>
<span class="line"><span>    const unit = EntIndexToHScript(event.entindex) as CDOTA_BaseNPC; // Cast to npc since this is the &#39;npc_spawned&#39; event</span></span>
<span class="line"><span>    // Give all real heroes (not illusions) the meepo_earthbind_ts_example spell</span></span>
<span class="line"><span>    if (unit.IsRealHero()) {</span></span>
<span class="line"><span>        if (!unit.HasAbility(&quot;meepo_earthbind_ts_example&quot;)) {</span></span>
<span class="line"><span>            // Add lua ability to the unit</span></span>
<span class="line"><span>            unit.AddAbility(&quot;meepo_earthbind_ts_example&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>Здесь мы можем увидеть несколько вещей. Во-первых, <code>event: NpcSpawnedEvent</code>, который описывает тип события, требуемого для этой функции. Это имеет два преимущества: во-первых, если вы используете несовместимое событие и обратный вызов, Typescript немедленно уведомит вас об этом. Во-вторых, эта функция знает, какие параметры вам предоставлены для использования.</p><p>Если вы не уверены, какой тип вам следует использовать, вы можете навести указатель мыши на <code>event</code> в вызове прослушивателя событий, и Typescript сообщит вам, к какому типу относится это событие. Например, при наведении курсора на событие <code>npc_spawned</code> вы увидите тип <code>NpcSpawnedEvent</code>:</p><p><img src="`+i+`" alt="Event type of predefined events"></p><p>Поскольку событие сработало, мы знаем, что что-то породило. В самой функции мы хотим знать, что породило, и обратиться к этому. Если мы проверим свойства события <code>NpcSpawnedEvent</code>, то увидим, что оно имеет два свойства: <code>entindex</code>, имеющее тип EntityIndex, и <code>is_respawn</code>, имеющее логический тип.</p><p>:::информация Вы можете найти типы в редакторе, щелкнув тип и нажав F12. :::</p><p>Энтиндекс относится к индексу сущности, который соответствует порожденной сущности. Если бы мы хотели получить саму сущность, нам нужно было бы привести ее к дескриптору, что можно сделать, вызвав <code>EntIndexToHScript</code>. Затем вы можете обратиться к этому объекту (обычно к юниту) и сделать все, что вам нужно, когда юнит появится. Вы также можете использовать свойство <code>is_respawn</code>, чтобы определить, возродился ли этот юнит, если он появлялся не в первый раз.</p><h2 id="пользовательские-события" tabindex="-1">Пользовательские события <a class="header-anchor" href="#пользовательские-события" aria-label="Permalink to &quot;Пользовательские события&quot;">​</a></h2><p>В вероятном случае, когда встроенные события не охватывают ситуацию, в которой вы хотите вызвать событие, Dota позволяет вам создавать собственные события. Как и в случае со встроенными событиями, Typescript играет большую роль в создании пользовательских событий и обеспечении осмысленности типов этих событий.</p><p>Прежде чем мы начнем, мы должны сначала определить событие. Для этого мы используем файл .d.ts. Если хотите, вы можете узнать больше о файлах .d.ts <a href="https://en.wikipedia.org/wiki/TypeScript#Declaration_files" target="_blank" rel="noreferrer">here</a>. Суть в том, что мы используем файлы .d.ts для описания Typescript типов вещей, доступных глобально.</p><p>Перейдите к <code>/src/common/events.d.ts</code>. Там вы можете использовать интерфейс <code>CustomGameEventDeclarations</code>, чтобы добавить столько пользовательских событий, сколько захотите. Шаблон разработал пользовательские события, которые будут извлекаться из событий, показанных в этом интерфейсе. Мы видим, что у него уже есть событие <code>example_event</code>, которое будет использоваться в качестве его имени, и тип <code>ExampleEventData</code>, который позже определяется как объект с различными свойствами, например <code>myNumber</code>.</p><p>:::информация Папка <code>/common</code> составлена ​​для всех типов, составлена ​​как для серверной стороны, так и для панорам, таких как события или сетевые таблицы. Это означает, что вы можете определить событие один раз, и обе стороны могут увидеть и использовать это событие. :::</p><p>Если вы хотите запустить пользовательское событие, вы можете использовать для этого функцию <code>CustomGameEventManager.Send_ServerToPlayer</code>. Существуют и другие варианты этой функции, но если проще, этот вариант отправляет событие конкретному игроку. В этом случае первый аргумент определяет, какому игроку отправить событие, а второй аргумент определяет, какое событие оно должно инициировать для этого игрока. Обратите внимание, что вы можете использовать только пользовательские события, которые были определены в интерфейсе <code>CustomGameEventDeclarations</code> — в противном случае Typescript выдаст ошибку. Третий аргумент формируется на основе выбранного события и обеспечивает отправку события со всей необходимой информацией для этого события.</p><p>Вы можете найти пример вызова функции <code>CustomGameEventManager.Send_ServerToPlayer</code> в <code>GameMode.ts</code>, который покажет, как все это связано друг с другом.</p><h2 id="таимеры" tabindex="-1">Таймеры <a class="header-anchor" href="#таимеры" aria-label="Permalink to &quot;Таймеры&quot;">​</a></h2><p>Таймеры — это библиотека, написанная на lua. Мы можем использовать библиотеку таймеров для задержки действий на определенное время, после чего вызывается функция обратного вызова. Его можно использовать в качестве задержки или повторного вызова, который происходит, например, каждые несколько секунд.</p><p>:::информация Таймеры написаны на lua. Вместо преобразования в Typescript мы используем файл <code>timers.d.ts</code>, чтобы описать Typescript структуру таймеров, что позволяет нам использовать библиотеку таймеров как есть. :::</p><p>Возвращаясь к <code>GameMode.ts</code>, файл содержит пару примеров таймеров. В обоих случаях исполнение простое. Давайте рассмотрим один из них:\`\`\` ts // Automatically skip setup in tools if (IsInToolsMode()) { Timers.CreateTimer(3, () =&gt; { GameRules.FinishCustomGameSetup(); }); }</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Это фрагмент кода, который срабатывает, когда игра переходит на экран «Настройка пользовательской игры», где игроки могут распределять себя по командам. Чтобы разработчикам не приходилось ждать на этом экране при каждом запуске, мы добавили проверку — если это в режиме инструментов (то есть мы запускаем игру из инструментов Dota Workshop), то мы создаем таймер. Через 3 секунды мы запускаем \`GameRules.FinishCustomGameSetup();\`, который переходит к следующему шагу.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Обратите внимание, что код не ждет завершения таймера. Создается таймер, и код немедленно переходит к следующей строке. Когда в игре проходит указанное количество времени, таймер разрешается, выполняя предоставленную ему функцию обратного вызова.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Таймеры можно настроить на повтор, вернув числовое значение, обозначающее секунды. Например, мы могли бы создать следующий таймер:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>ts Timers.CreateTimer(5, () =&gt; { print(<code>The current time in dota is: \${GameRules.GetDOTATime()}</code>); return 1; });</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>При этом будет создан таймер, выполнение которого первоначально занимает 5 секунд. Поскольку мы возвращаем 1, таймер будет повторяться каждую секунду. В этом примере при каждом выполнении будет выводиться текущее время и сообщение.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Обратите внимание, что вы можете возвращать разные значения при каждом запуске, чтобы таймер запускался с разными задержками при каждом повторении.</span></span>
<span class="line"><span>Кроме того, возврат без значения или с \`undefined\` приведет к тому, что таймер больше не будет повторяться, что можно использовать в качестве условия остановки для повторяющегося таймера.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:::информация</span></span>
<span class="line"><span>Таймеры уважают паузы. Это означает, что они не будут выполняться, пока игра приостановлена, и выполнение кода будет отложено до тех пор, пока игра не будет снята с паузы.</span></span>
<span class="line"><span>:::</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Использование таймеров с промисами для задержки кода</span></span>
<span class="line"><span>Иногда вам нужно создать последовательность эффектов, которые происходят один за другим, но не сразу, а по истечении короткого периода времени. Хотя вы могли бы сделать это в таймерах, это привело бы к созданию серии обратных вызовов, что может сделать код беспорядочным и трудным для чтения.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Вместо этого мы могли бы обернуть таймер в промис. Если вы не знаете о Promises, вы можете прочитать [Promises in W3Schools](https://www.w3schools.com/js/js_promise.asp). Мы также будем использовать промисы с концепцией async/await, которую вы можете прочитать на [Async/Awaits in W3Schools](https://www.w3schools.com/js/js_async.asp). Это довольно сложные темы, поэтому не стесняйтесь обсуждать их с нами в Moddota или искать дополнительные статьи или видео по ним.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Давайте создадим функцию \`sleep\`, которая будет возвращать обещание, которое разрешается при выполнении таймера. Обычно я создаю все служебные функции, подобные этой, в другом файле, обычно называемом \`utils.ts\`. Перейдите в папку \`/src/vscripts/libs\` и создайте файл с именем \`utils.ts\`.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Там мы хотим создать функцию сна, которая выглядит следующим образом:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>ts export function sleep(duration: number) { return new Promise((resolve, reject) =&gt; { Timers.CreateTimer(duration, () =&gt; resolve(&#39;&#39;)); }); }</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Как видите, функция возвращает обещание, которое будет выполнено в какой-то момент в будущем. Вы можете подождать, пока обещание будет разрешено с помощью async/await. Для целей этого примера давайте рассмотрим функцию \`OnNpcSpawned\`. Он преобразует энтиндекс в юнит, а затем проверяет, настоящий ли это герой (например, не иллюзия). Затем, если у него нет способности, он немедленно дает ему эту способность. Давайте представим, что вместо этого мы хотим дать ему эту способность по прошествии 5 секунд.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Во-первых, поскольку мы хотим использовать \`await\`, мы должны преобразовать эту функцию в асинхронную функцию. Добавьте ключевое слово \`async\` прямо перед именем функции:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>ts private async OnNpcSpawned(event: NpcSpawnedEvent) { <code>Затем импортируйте \`sleep\` из \`utils.ts\`:</code> ts import { sleep } from &#39;./lib/util&#39;;</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>И теперь мы можем спать на 5 секунд, используя await:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>ts private async OnNpcSpawned(event: NpcSpawnedEvent) { // After a hero unit spawns, apply modifier_panic for 8 seconds const unit = EntIndexToHScript(event.entindex) as CDOTA_BaseNPC; // Cast to npc since this is the &#39;npc_spawned&#39; event // Give all real heroes (not illusions) the meepo_earthbind_ts_example spell if (unit.IsRealHero()) { if (!unit.HasAbility(&quot;meepo_earthbind_ts_example&quot;)) { // Wait for 5 seconds before giving it the ability await sleep(5);</p><pre><code>        // Add lua ability to the unit
        unit.AddAbility(&quot;meepo_earthbind_ts_example&quot;);
    }
}
</code></pre><p>}</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Как видите, это делает код очень чистым и простым в использовании. Таким образом, неповторяющиеся таймеры можно перевести в спящий режим, чтобы добиться того же результата с более чистым потоком кода.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Есть много вещей, для которых вы можете использовать async/await, например, ожидание попадания следящих снарядов, ожидание завершения анимации и т. д.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,45)])])}const h=n(t,[["render",l]]);export{m as __pageData,h as default};
